////////////////// 组队模式 ///////////////////////
message OptTeamCreate {
	optional int32 leader_uid = 1;
	repeated TeamUserInfo members = 2; // 队伍成员信息
}

message OptTeamReady {
	optional int32 uid = 1;
	optional bool ready = 2; 
}

message OptTeamQuit {
	optional int32 uid = 1;
	optional bool dismiss_team = 2; //解散退伍标志
}

message OptTeamReconn {
	optional OptTeamCreate members = 1;
	repeated OptTeamReady ready = 2;
	optional uint64 teamid = 3;
	optional int32 uid = 4;
	optional int32 gameid = 5;
}

//0x020B 队伍操作
message ReqTeamOperation {
	optional int32 ope = 1; //1-创建 2-准备 3-退出 4-重连 5-队伍心跳 6-同步资产变化
	optional OptTeamCreate create = 2; 
	optional OptTeamReady ready = 3;
	optional OptTeamQuit quit = 4;
	optional int32 gameid = 5;
	optional uint64 heartbeat_teamid = 6;
	optional OptTeamReconn reconn = 7; //服务端用,客户端不填
	optional int32 uid = 8; //自己的用户ID
}
// 0x020C 队伍操作响应
message RspTeamOperation {
	optional int32 retcode = 1; //0-操作错误  1-创建 2-准备 3-退出 4-重连推送 5: 心跳
	optional string errcode = 2; //错误原因
	optional uint64 teamid = 3; // 队伍id
	optional OptTeamCreate create = 4;
	optional OptTeamReady ready = 5;
	optional OptTeamQuit quit = 6;
	optional OptTeamReconn reconn = 7;
	optional int32 gameId = 8; // 游戏id
	optional int32 error_code = 9;
	repeated TeamUserInfo syncdata = 10;
}

message TeamUserInfo {
	optional int32 uid = 1;
	optional string str_key = 2;
	optional string str_info = 3;
	optional string ext_info = 4;
	optional int32 flag = 5;
	optional int64 money = 6;
}
//0x020D 队伍匹配
message ReqTeamMatch {
	optional int32 gameid = 1;
	optional int32 level = 2;
	optional TeamUserInfo leader = 3;
	optional uint64 teamid = 4; //单人不填
}

//0x020E 队伍匹配响应
message RspTeamMatch {
	optional int32 retcode = 1; //0-匹配错误 1-匹配中
	optional string errcode = 2; //错误码
	optional int32 level = 3; //游戏场次level
	optional int32 error_code = 4;
}
